import { TrendingDownIcon, TrendingUpIcon } from "lucide-react"

import { cn } from "@/lib/utils"
import { Badge } from "@/components/ui/badge"

export interface StatWidgetProps {
  label: string
  value: string
  /** Change since the previous period, e.g. "+20.1%". */
  delta?: string
  trend?: "up" | "down" | "flat"
  /** Small note under the value, e.g. "vs. last month". */
  hint?: string
  className?: string
}

/**
 * A single headline number.
 *
 * Every colour here comes from a theme token, so the widget follows the host
 * app's palette and dark mode with no `dark:` overrides of its own.
 */
export function StatWidget({
  label,
  value,
  delta,
  trend = "flat",
  hint,
  className,
}: StatWidgetProps) {
  const TrendIcon = trend === "up" ? TrendingUpIcon : trend === "down" ? TrendingDownIcon : null

  return (
    <div className={cn("flex h-full flex-col justify-center gap-1", className)}>
      <span className="text-muted-foreground text-xs font-medium tracking-wide uppercase">
        {label}
      </span>
      <div className="flex flex-wrap items-baseline gap-2">
        <span className="text-2xl font-semibold tabular-nums">{value}</span>
        {delta && (
          <Badge variant={trend === "down" ? "destructive" : "secondary"}>
            {TrendIcon && <TrendIcon data-icon="inline-start" />}
            {delta}
          </Badge>
        )}
      </div>
      {hint && <span className="text-muted-foreground text-xs">{hint}</span>}
    </div>
  )
}

import { cn } from "@/lib/utils"
import { Progress } from "@/components/ui/progress"

export interface ProgressWidgetRow {
  label: string
  value: number
  max?: number
  /** Optional right-hand caption. Defaults to a percentage. */
  caption?: string
}

export interface ProgressWidgetProps {
  rows: ProgressWidgetRow[]
  className?: string
}

/** A stack of labelled progress bars — quotas, goals, capacity. */
export function ProgressWidget({ rows, className }: ProgressWidgetProps) {
  return (
    <div className={cn("flex h-full flex-col justify-center gap-3", className)}>
      {rows.map((row) => {
        const max = row.max ?? 100
        const percent = max === 0 ? 0 : Math.round((row.value / max) * 100)
        return (
          <div key={row.label} className="flex flex-col gap-1.5">
            <div className="flex items-baseline justify-between gap-2">
              <span className="truncate text-sm font-medium">{row.label}</span>
              <span className="text-muted-foreground text-xs tabular-nums">
                {row.caption ?? `${percent}%`}
              </span>
            </div>
            <Progress value={percent} aria-label={`${row.label}: ${percent}%`} />
          </div>
        )
      })}
    </div>
  )
}

"use client"

import { Area, AreaChart, Bar, BarChart, CartesianGrid, XAxis } from "recharts"

import { cn } from "@/lib/utils"
import {
  ChartContainer,
  ChartTooltip,
  ChartTooltipContent,
  type ChartConfig,
} from "@/components/ui/chart"

export interface ChartWidgetProps {
  data: { label: string; value: number }[]
  /** Legend/tooltip name for the series. */
  seriesName?: string
  variant?: "bar" | "area"
  /** Any chart token, e.g. "var(--chart-1)". */
  color?: string
  className?: string
}

/**
 * A compact chart sized to fill its grid cell.
 *
 * `ChartContainer` defaults to `aspect-video`; a dashboard widget has a height
 * fixed by the grid instead, so we swap in `aspect-auto` and fill the cell.
 *
 * Animation is off deliberately. The grid re-measures on resize, and replaying
 * a grow-from-zero intro on every measure both looks broken and can leave bars
 * stranded at zero height if measures arrive faster than the animation.
 */
export function ChartWidget({
  data,
  seriesName = "Value",
  variant = "bar",
  color = "var(--chart-1)",
  className,
}: ChartWidgetProps) {
  const config = {
    value: { label: seriesName, color },
  } satisfies ChartConfig

  const axis = (
    <>
      <CartesianGrid vertical={false} />
      <XAxis
        dataKey="label"
        tickLine={false}
        axisLine={false}
        tickMargin={8}
        minTickGap={8}
      />
      <ChartTooltip content={<ChartTooltipContent />} />
    </>
  )

  return (
    <ChartContainer
      config={config}
      className={cn("aspect-auto h-full w-full", className)}
    >
      {variant === "area" ? (
        <AreaChart data={data} margin={{ left: 4, right: 4, top: 4 }}>
          {axis}
          <Area
            dataKey="value"
            type="natural"
            stroke="var(--color-value)"
            fill="var(--color-value)"
            fillOpacity={0.2}
            strokeWidth={2}
            isAnimationActive={false}
          />
        </AreaChart>
      ) : (
        <BarChart data={data} margin={{ left: 4, right: 4, top: 4 }}>
          {axis}
          <Bar dataKey="value" fill="var(--color-value)" radius={4} isAnimationActive={false} />
        </BarChart>
      )}
    </ChartContainer>
  )
}

import { cn } from "@/lib/utils"

export interface NotesWidgetProps {
  /**
   * Rendered prose. Pass a markdown renderer's output, streamed assistant
   * output, or plain JSX — Typeset styles the resulting elements either way.
   */
  children: React.ReactNode
  className?: string
}

/**
 * A prose widget styled by Typeset.
 *
 * Text-heavy widgets are where a dashboard usually falls apart: headings and
 * lists arrive unstyled because the surrounding app resets them, so every
 * project re-styles the same elements by hand. Typeset handles all of it from
 * one CSS file, driven by three custom properties.
 *
 * `typeset-widget` tightens the rhythm for a small grid cell. It is defined in
 * the dashboard theme CSS; adjust it there, or override inline:
 *
 *     <NotesWidget className="[--typeset-flow:1.5em]">…</NotesWidget>
 */
export function NotesWidget({ children, className }: NotesWidgetProps) {
  return (
    <div className={cn("typeset typeset-widget h-full overflow-auto", className)}>
      {children}
    </div>
  )
}
